// datapack.h -- the generated tables (src/data/*.h) loaded at run time, for a DATA-FREE build (CT_DATAFREE).
//
// A data-free Belthasar compiles every table, and every numeric #define the compiler does not need as a constant, as
// zeroed storage (src/tables/tables_storage.c, generated by tools/gen/pack_tables.py) and fills it at startup from the
// TABLE PACK the player's setup made from their ROM (ct_tables.dat; format: tools/gen/pack_tables.py's docstring,
// docs/ROM.md). The loader refuses any pack that does not match this build exactly: the pointer size and byte order,
// the set of tables, each table's size and layout hash, the set of #defines, the value of every one compiled in (an
// array bound). A normal build (ct.exe, a developer's Belthasar) includes the real headers and never calls it.
#ifndef CT_DATAPACK_H
#define CT_DATAPACK_H

#include <stddef.h>

// One table: its storage and size, its layout hash, and where it holds pointers -- the offsets of the pointer members
// inside one element of elemSize bytes (the type under every dimension), repeated for every element.
typedef struct {
  const char* name; void* data; size_t size; unsigned long long layout;
  unsigned elemSize; const unsigned* ptrOffs; int nPtr;
} CtTableDesc;
// One numeric #define of the shapes. A COMPILED-IN one (var NULL: an array bound the compiler needs) carries the
// shapes' value, which must equal the pack's. A RUN-TIME one is the variable its data-free #define names
// (`#define X ctDef_X`), of the literal's C type (kind), which the loader fills from the pack.
enum { CT_TBL_DEF_INT = 1, CT_TBL_DEF_UINT = 2 };
typedef struct { const char* name; long long value; void* var; int kind; } CtTableDefine;

// The registry tables_storage.c defines (one entry per table, sorted by name; every #define).
extern const CtTableDesc ctTableDescs[];
extern const int ctTableDescCount;
extern const unsigned long long ctTableSetHash;
extern const CtTableDefine ctTableDefines[];
extern const int ctTableDefineCount;

// Fill every table from the pack at `path`. Returns 1, or 0 with the reason in err (the tables are then unusable).
int CtDataPackLoad(const char* path, char* err, size_t errLen);

// 1 = the CTAS container at `path` carries the tables (their header entry): a ct_tables.dat, or a ct_assets.dat the
// player's setup wrote them into (tools/gen/pack_tables.py pack --into).
int CtDataPackFileHasTables(const char* path);

// 1 = the pack at `path` is laid out for THIS build (its header: the format, the pointer size, the byte order, the set
// of tables). An earlier version's data fails it, so the start shows the setup instead of a game that quits at once.
int CtDataPackFileMatches(const char* path);

// Belthasar's startup: find the pack and load it. In order: `--tables <path>`, $CT_TABLES, the --assets/--datonly
// file itself when it carries the tables, ct_tables.dat beside it, ct_tables.dat in the working directory.
// Returns 1, or 0 with the reason in err.
int CtDataPackLoadForArgs(int argc, char** argv, char* err, size_t errLen);

// The file the tables came from (after a successful load), else NULL.
const char* CtDataPackPath(void);

#endif
